@loyalty-discount
Feature: Loyalty discount

  @happy-path @edge-case
  Scenario Outline: Returning customer is charged the subtotal minus the reduction of their loyalty tier
    Given a returning customer in the <tier> tier
    When a basket subtotal of <subtotal> cents is priced
    Then the customer is charged <charged> cents

    Examples:
      | tier   | subtotal | charged |
      | Bronze | 10000    | 9500    |
      | Silver | 10000    | 9000    |
      | Gold   | 10000    | 8500    |
      | Bronze | 7        | 7       |
E
cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/LoyaltyDiscountAcceptanceTests.cs <<'E'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public sealed class LoyaltyDiscountAcceptanceTests
{
    // Returning customer is charged the subtotal minus the reduction of their loyalty tier
    [Theory]
    [InlineData(LoyaltyTier.Bronze, 10000, 9500)]
    [InlineData(LoyaltyTier.Silver, 10000, 9000)]
    [InlineData(LoyaltyTier.Gold, 10000, 8500)]
    [InlineData(LoyaltyTier.Bronze, 7, 7)]
    public void Returning_customer_is_charged_the_subtotal_minus_the_reduction_of_their_loyalty_tier(
        LoyaltyTier tier, int subtotalCents, int chargedCents)
    {
        var useCase = new CalculateLoyaltyDiscount();

        var quote = useCase.Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier));

        Assert.Equal(chargedCents, quote.TotalCents);
    }
}
